"""Maintain Step 8 reports and READMEs from generated maps and test evidence."""
from pathlib import Path
import json,argparse,xml.etree.ElementTree as ET
import pandas as pd
B=Path(__file__).resolve().parents[1];ROOT=B.parent


def markdown_table(frame):
    return '\n'.join(['| '+' | '.join(frame.columns)+' |','| '+' | '.join(['---']*len(frame.columns))+' |']+
      ['| '+' | '.join(f'{x:.6f}' if isinstance(x,float) else str(x) for x in row)+' |' for row in frame.itertuples(index=False,name=None)])


def document(output):
    summary=pd.read_csv(output/'summary.csv',dtype={'trip_id':str});timings=pd.read_csv(output/'runtime_by_trip.csv',dtype={'trip_id':str})
    validation=json.loads((output/'validation_report.json').read_text());browser=json.loads((output/'browser_verification.json').read_text())
    examples=json.loads((output/'examples.json').read_text());metadata=json.loads((output/'run_metadata.json').read_text())
    initial_path=output/'initial_run_metadata.json';initial=json.loads(initial_path.read_text()) if initial_path.exists() else metadata
    suites=list(ET.parse(output/'pytest-results.xml').getroot().iter('testsuite'))
    tests={k:sum(int(s.get(k,0)) for s in suites) for k in ['tests','failures','errors','skipped']}
    assert validation['status']=='passed' and browser['status']=='passed' and tests['failures']==tests['errors']==0
    layer_table=pd.DataFrame([
      ['GPS observations','Blue','On','All valid original GPS points. Canvas-rendered circles; popup index/timestamp and every retained candidate: arc ID, distance, heading disagreement, RF p(+).'],
      ['Raw GPS trace','Blue, dashed','Off','Actual raw coordinate sequence, split at existing temporal segments and invalid time/coordinates. A raw trace is not a road prediction.'],
      ['Candidate directed roads','Amber','Off','All unique retained candidate arc geometries. Popup has original endpoints/arc ID and nearest-distance representative row, explicitly labelled; GPS popups show per-observation detail.'],
      ['Random Forest selected roads','Green','Off','All unique original arcs selected by frozen classifier Top-1. Full candidate arcs, with observation count/examples; does not imply full traversal.'],
      ['Viterbi selected candidate roads','Purple','Off','Full candidate arcs selected by saved decoder, separate from reconstructed partial road travel.'],
      ['Reconstructed route','Red','On','Every saved ordered route occurrence, including intermediate roads and repeated loops, clipped at each segment entry/exit fraction. Single-position segments become points.'],
      ['Intermediate reconstructed arcs','Orange','On','Exact subset of saved route occurrences whose role is intermediate. No interpolated or guessed intermediate roads.'],
      ['Reference route — evaluation only','Teal, dashed','Off','Supplied student-test reference arc occurrences. Independent optional overlay, drawn as individual directed arcs; no artificial links between reference breaks.'],
      ['Temporal gaps','Grey circles','On','Markers at saved temporal_gap restart observations. No GPS or road chord crosses a gap.'],
      ['Infeasible transitions','Magenta circles','On','Markers at saved no_feasible_transition restarts and other usable restart reasons. Infeasibility can reflect bounds, not proven physical disconnection.'],
      ['Directed-unreachable selections','Magenta circles','On','Saved classifier and Viterbi pair diagnostics; variant/from/to observations in popup. Both variants remain available in every before/after view.'],
      ['Unmatched observations','Near-black circles','On','Explicit no-candidate/unmatched observation markers when coordinates are valid. Actual ten student trips have zero unmatched decoder outputs.'],
      ['Travel direction','Dark red arrows','Off','Direction glyphs on up to 160 actual route arc occurrences. Arrow wings are display symbols, never route geometry.'],
      ['Context directed roads','Grey','Off','Original endpoint geometry within GPS bounds + 0.002 degrees. Up to 2,000 evenly selected arcs when larger; context sampling only.'],
      ['Context nodes','Grey circles','Off','Up to 600 original road nodes from displayed context arcs. Popup original node ID.'],
      ['GPS start and end','Green Start / red End labels','On','Original first/last valid GPS positions, with their observation indices/timestamps. Invalid observations remain counted in metadata.']
    ],columns=['Layer','Colour','Default','Meaning'])
    example_table=pd.DataFrame(examples)
    commands=r'''cd .\PathSnap\laptop1_backend
.\.venv\Scripts\python.exe scripts\visualize_step8.py
Start-Process .\outputs\step8\index.html
# Open the largest measured improvement directly:
Start-Process .\outputs\step8\maps\00000009.html
# Focused tests and full suite, using new project-local temp directories:
.\.venv\Scripts\python.exe -m pytest tests\test_step8.py -q --basetemp=pytest_temp\step8_focused_reproduce
.\.venv\Scripts\python.exe -m pytest -q --basetemp=pytest_temp\step8_full_reproduce --junitxml=outputs\step8\pytest-results.xml
# Browser checks need Chrome or Edge and no Python HTTP server:
.\.venv\Scripts\python.exe scripts\preview_step8.py
.\.venv\Scripts\python.exe scripts\verify_step8.py
.\.venv\Scripts\python.exe scripts\document_step8.py'''
    text='\n\n'.join([
      '# Step 08: Interactive Folium geographic visualisation',
      '## Objective and actual completion',
      f"Completed {len(summary)} interactive student-test trip maps for {int(summary.observations.sum()):,} GPS observations, with {int(summary.decoded_segments.sum())} separate decoded route segments. The index opens directly from outputs/step8/index.html. Maps compare original GPS, candidates, classifier-only selections, Viterbi candidate states and complete reconstructed road paths. Before/After/Compare buttons and layer controls change visibility only; every result comes from the frozen Step 7 outputs.",
      'Scope is Step 8 only. No classifiers were retrained, no Optuna study was resumed, no dataset/candidate processing was rerun, and no HMM/Viterbi reconstruction job was executed. Production artifacts from Steps 1–7 and all seven earlier per-step READMEs are unchanged. Existing full-suite tests include their normal small fixture fits and saved-pipeline reload checks; no production training job is part of map generation or verification. No FastAPI, Streamlit, two-laptop network integration or deployment ZIP exists.',
      '## Inputs and existing implementation reused',
      'The Folium, FeatureGroup, original endpoint geometry, valid-coordinate checks, layer control and OSM approach follow the existing candidate_visuals.py and visuals.py. Those older maps/modules are preserved. The new reusable module extends them to complete saved route comparison and data-rich GeoJSON layers.',
      'Per-trip inputs: data/processed/step3/student_test/<trip>/observations.parquet and features.parquet; Step 2 road_arcs.parquet; original .nodes; Step 7 probabilities.parquet, classifier_selected.parquet, decoded.parquet, route_arcs.parquet, transitions.parquet and both pair-diagnostic tables. Step 7 complete.json checksums validate prediction outputs before rendering. The 25-feature inference table is used only for popup diagnostics; no model is loaded. Existing per_trip_comparison.csv supplies all displayed accuracy and continuity values. No values are inferred from map appearance.',
      'Reference isolation is structural: build_prediction_layers has no reference input. It completes prediction layers before load_trip_layers reads an optional supplied student .route for reference_features. The overlay starts hidden, is labelled evaluation-only throughout, and cannot affect frozen predictions. Changing or removing the reference only changes the overlay and map identity. These student-development maps intentionally include legitimate supplied references; future hidden-evaluator API/UI responses must retain the assignment’s server-side label policy rather than exposing an evaluation-reference bundle.',
      '## Interactive map implementation',
      'Folium 0.20.0 generates Leaflet maps with OpenStreetMap tile attribution, zoom/pan, scale control, a collapsed layer chooser, start/end labels, hover tooltips and click popups. The floating trip panel contains actual per-trip Top-1/continuity, navigation back to the index, and three visibility modes. Before enables RF selected roads; After enables reconstructed route plus intermediates; Compare enables both. Optional reference/direction/selected-state layers reset off when these mode buttons are used. Boundary/unmatched markers and GPS remain available independently.',
      markdown_table(layer_table),
      'There are 16 overlay layers plus the OSM base-layer selector. Empty diagnostic overlays remain available in the layer control with zero features. Candidate roads are deduplicated by original arc ID rather than drawing the same road once per observation; no retained observation or route occurrence is dropped. Each GPS popup retains all of that observation’s candidate rows. Heading disagreement or other nonfinite values display unavailable rather than fabricated zero. Sampled context/arrow limits are recorded and do not alter predictions.',
      '## Coordinates, partial arcs and segment boundaries',
      'GeoJSON uses [longitude, latitude]; Leaflet locations/bounds use [latitude, longitude]. Source coordinates retain the existing WGS84 assumption. Roads are the supplied straight from-node→to-node endpoint geometry; no curved road geometry exists in these artifacts. Fractional positions are the saved directed projected-arc fractions. Visual clipping linearly interpolates those endpoint coordinates; it preserves the source straight-segment approximation and is not a new geodesic road shape.',
      'For each saved segment, route_order and original arc occurrences are retained. The first occurrence begins at the first selected fraction; the last ends at the last selected fraction; intermediate occurrences use full endpoints. If the segment has one occurrence, both clipping fractions apply to that same arc. An identical start/end position renders a point. Genuine loop occurrences are not deduplicated. Adjacent occurrences must share directed endpoints, otherwise rendering rejects the saved segment. Every occurrence is a separate geographic feature, so the renderer never draws a shortcut between GPS observations or between decoded segments.',
      'Raw GPS trace segments follow existing temporal segmentation and invalid observations are not joined. Temporal gaps, infeasible restarts and proven directed-unreachable adjacent selections are point markers, not misleading connecting lines. A no_feasible_transition marker is not necessarily topological disconnection because routing/movement bounds can also cause it. Reference arcs are also drawn individually. Map routes contain all 7,387 saved route occurrences across 277 segments.',
      '## Trip navigation, measured comparisons and examples',
      'index.html lists every trip, observation count, decoded segments, classifier/Viterbi Top-1, percentage-point difference, direct continuity and a relative map link. Metrics are copied from Step 7, not recomputed using new labels. Pooled Top-1 remains 85.179075% versus 87.145116%; it is conditional on 14,547 qualified candidate-present observations. The 574 candidate misses, ambiguous/unalignable/excluded labels and prior heuristic-reference limitations remain unchanged. These are development observations, not an untouched evaluator test or independent full-route correctness claim.',
      markdown_table(summary[['trip_id','observations','decoded_segments','classifier_top1','viterbi_top1','improvement_pp','classifier_continuity','viterbi_continuity']]),
      markdown_table(example_table),
      'Example pages under examples/ redirect to the corresponding complete trip map using relative links; no second set of route data is generated. Largest Top-1 gain is trip 00000009 (+6.667 pp). Trip 00000056 has 3,956 observations with multiple retained candidates; this is a candidate-ambiguity inspection case, not a measured count of road intersections or ambiguous ground-truth labels. Trip 00000076 has 39 temporal gaps and two infeasible restarts. Trip 00000065 declines by 3.306 pp despite increased continuity, illustrating that a plausible connected route can reinforce a wrong road choice. These examples were chosen from saved measurements, not fabricated scenarios.',
      '## Portable local assets and scalability',
      'The package includes local Leaflet 1.9.3 JS/CSS, jQuery 3.7.1, five Leaflet images and both library licences under assets/. Libraries match the existing Folium default versions; no new Python dependencies were added. HTML loads ../assets/leaflet.js, jquery.min.js and leaflet.css and embeds all map data. No fetch of a JSON file or Python server is required. Keep index.html, maps/, assets/ and examples/ together when copying. data/ and metadata/ support auditing and future reuse but are not network-loaded by the browser.',
      'Normal OSM base tiles require internet. With tiles unavailable, GPS/road layers, controls, popups and metrics still work on a grey background. No tile bundle is downloaded or packaged. ensure_assets reuses checksum-valid local files. A missing/corrupt asset is retrieved from its fixed public source; on Windows certificate-store failures it uses hidden PowerShell Invoke-WebRequest with TLS validation retained. It never disables certificate verification. Asset sources, versions, sizes and SHA-256 values are in assets/manifest.json.',
      f"Canvas rendering, deduplicated candidate/selected arcs, GeoJSON batches and bounded optional context keep maps manageable. Complete route data is not simplified or sampled. Trip HTML ranges from {summary.html_bytes.min()/2**20:.2f} to {summary.html_bytes.max()/2**20:.2f} MiB; total HTML {summary.html_bytes.sum()/2**20:.2f} MiB. Some maps are large because all GPS candidate popups and route occurrences are retained. Desktop browser verification opened every map successfully; performance on low-memory devices was not benchmarked.",
      '## Files, function contracts and execution flow',
      '| File / function | Inputs → outputs / purpose |\n|---|---|\n| src/pathsnap/map_visualization.py: point_feature, arc_feature | Original coordinates/arc IDs/fractions → validated GeoJSON points or directed partial/full segments |\n| reconstructed_features | Saved route occurrences + selected endpoint fractions → ordered per-segment route features; rejects invalid connectivity |\n| build_prediction_layers | Saved observations/features/probabilities/selections/routes/diagnostics + nodes/arcs → reference-free overlay collections and display metadata |\n| reference_features | Supplied student route + original geometry → independent evaluation-only overlay |\n| render_map | Layer collections, bounds and frozen metrics → local-asset HTML with controls and diagnostics |\n| stable_html | Folium HTML → deterministic element identifiers, including generated JS function names; no global RNG changes |\n| scripts/visualize_step8.py: ensure_assets, load_trip_layers, choose_examples, write_index, run | Existing files → validated assets, per-trip HTML/GeoJSON/checkpoints, measured examples/index/summary; resumable |\n| scripts/preview_step8.py | Generated local HTML → native headless Chrome/Edge live-layer/popup checks and preview PNGs; no server |\n| scripts/verify_step8.py | Saved map data + originals/Step 7/metrics → independent geometry/checksum/link/browser report |\n| scripts/document_step8.py | Actual outputs, validation and JUnit → this reference, STEP8_SUMMARY.md and three main READMEs |\n| tests/test_step8.py | Small explicit geographic fixtures → geometry, direction, segmentation, leakage, popup/layer and deterministic HTML tests |',
      'Execution: verify/download missing local assets → verify Step 7 completion checksums → join saved candidate probability identities → construct reference-free display layers → append optional reference overlay → render atomic HTML/GeoJSON and checkpoint → write relative index/example links → browser/geometry verification → focused/full tests → documentation. No training or decoder module is imported by the visualisation modules/scripts.',
      'outputs/step8/ contains index.html; maps/<trip>.html (ten); data/<trip>.json (sixteen layer collections and display metadata); metadata/<trip>.json (input/code/version/asset identity, output checksums, size/time); examples.json and examples/<trip>.html (four); assets/ plus manifest and licences; summary.csv; runtime_by_trip.csv; run_metadata.json; initial_run_metadata.json; protected_artifacts.json; browser_verification.json; validation_report.json; pytest-results.xml; test-results.txt; STEP8_SUMMARY.md. previews/ contains index.png, 00000009.png, 00000065.png and per-trip browser logs/results.',
      '## Preview references',
      'Open the real interactive index: [index.html](../../laptop1_backend/outputs/step8/index.html). Preview images: [index](../../laptop1_backend/outputs/step8/previews/index.png), [improvement trip 00000009](../../laptop1_backend/outputs/step8/previews/00000009.png), [limitation trip 00000065](../../laptop1_backend/outputs/step8/previews/00000065.png). These links are relative from this docs/steps reference. The output summary copy lives in a different directory; use its neighbouring index.html/previews/ directly.',
      'Preview screenshots deliberately show offline overlays with OSM tile requests blocked to verify independence from external JS/CDNs and tiles. Normal map files retain online OSM configuration. No claim is made that the screenshots show loaded OSM background tiles.',
      '## Exact Windows PowerShell commands and reproducibility',
      '```powershell\n'+commands+'\n```',
      'Rerunning visualize_step8.py reuses HTML and GeoJSON only when input hashes, renderer/module code, library versions, local assets and output checksums match. Incomplete/corrupt or changed maps rebuild independently. Temporary writes replace HTML/JSON atomically; metadata is the final per-trip commit marker. --force rebuilds only visualisations. Use --output for a separate output folder. Completed maps never trigger classifier/decoder execution. The completed second invocation reused all ten maps. initial_run_metadata.json retains original generation timing; run_metadata.json/runtime_by_trip.csv describe the latest invocation while original per-map generation times remain in metadata.',
      f"First full generation loop: {initial['invocation_seconds']:.3f} seconds; latest resume loop: {metadata['invocation_seconds']:.3f} seconds; {metadata['reused_maps']} maps reused on that invocation. Dependency versions: {json.dumps(metadata['versions'])}. Deterministic element-ID canonicalization makes equivalent HTML byte-identical under unchanged inputs/library versions. Real trip 00000065 was regenerated in memory and matched its saved HTML exactly.",
      '## Tests and verification',
      '```json\n'+json.dumps(dict(tests=tests,validation=validation,browser=dict(status=browser['status'],maps_opened=browser['maps_opened'],index_opened=browser['index_opened'],local_assets_work_without_tiles=browser['local_assets_work_without_tiles'])),indent=2)+'\n```',
      'The focused suite passed 17 tests. Tests cover geographic coordinate order, directed fraction limits, reconstructed occurrence ordering and loops, intermediate membership, disconnected-segment rejection, single-position segments, popup fields, start/end markers, temporal splitting, invalid/missing-candidate observations, unreachable marker-only display, reference isolation, candidate identity validation and deterministic HTML. HTML tests recognize valid JSON-escaped layer labels; no geometry checks were weakened.',
      'The complete suite passed 167 tests, including all 150 previous tests, with zero failures/errors/skips. Explicit project-local --basetemp paths avoided the older inaccessible Windows temporary directory; use a new path when repeating. No permission restrictions or existing assertions were weakened. Native browser verification required normal process permissions because the restricted Chrome GPU process could not start; browser sandbox controls were not disabled.',
      'Independent verification checks 147,396 coordinate pairs, all 7,387 route occurrences/277 segment identities, clipping fractions and endpoint direction, no fabricated intermediate arcs, exact saved boundary markers, index/example/local-asset links, all displayed per-trip metrics, references as a separate overlay and 745 protected previous-stage files. Live browser tests opened all ten maps and the index, checked 16 overlay controls plus OSM base selector, canvas/GPS count, Before/After/Compare toggles, real GPS click popups and reference initially hidden/enabled. Zero JavaScript errors were reported. A second generation invocation reused all ten verified maps.',
      '## Limitations and Step 9 readiness',
      'Maps visualise existing outputs; they do not improve accuracy, repair candidate misses, resolve the two remaining topologically unreachable selected pairs, or turn 277 segments into one route. Straight source arcs approximate real curves; linear endpoint clipping shares that approximation. Reference qualification and candidate availability still condition accuracy. Context roads/nodes and arrows are bounded displays; GPS, candidates and reconstructed occurrences are complete. Blank background without online OSM is expected, not missing route data.',
      'All data/map generation remains on Laptop 1. Laptop 2 remains a documentation-only future HTTP UI placeholder. Reusable layer builders, GeoJSON sidecars, segment IDs, metadata and self-contained local map assets are ready for separately authorised Step 9 FastAPI integration. No API, Streamlit, cross-laptop networking or deployment ZIP has been built. Stop after Step 8.',
      'Changelog — 2026-11-18: completed interactive saved-output Folium maps, portable assets/index/examples, live browser and geometry verification, 17 focused tests, full regression tests and Step 8 documentation. Earlier step documents remain unchanged.'
    ])+'\n'
    (ROOT/'docs/steps/STEP_08_README.md').write_text(text,encoding='utf-8')
    # Preserve useful local preview links in the output-directory copy.
    output_text=text.replace('../../laptop1_backend/outputs/step8/','')
    (output/'STEP8_SUMMARY.md').write_text(output_text,encoding='utf-8')
    for path,prefix in [(ROOT/'README.md','docs/steps/'),(B/'README.md','../docs/steps/'),(ROOT/'laptop2_frontend/README.md','../docs/steps/')]:
        old=path.read_text(encoding='utf-8');marker='\n<!-- STEP8_CURRENT -->'
        if marker in old:old=old.split(marker)[0]
        old=old.replace('## Current status: Step 7 completed','## Historical Step 7 completion record')
        old=old.replace('**Steps 1–7 are implemented:**','**Steps 1–8 are implemented:**').replace('(Steps 1–7)','(Steps 1–8)')
        old=old.replace('Steps 1–7 are complete; Step 8 requires explicit approval.','Steps 1–8 are complete; Step 9 requires explicit approval.')
        old=old.replace('Steps 1–7 maintain this directory and documentation only.','Steps 1–8 maintain this directory and documentation only.')
        old=old.replace('Step 7 HMM/Viterbi; stop before Step 8','Step 7 HMM/Viterbi → Step 8 Folium maps; stop before Step 9')
        old=old.replace('- [ ] Step 8 final Folium visualisation/application; not started.','- [x] Step 8 saved-output Folium visualisation; see current reference.')
        addition=f"\n\n## Current status: Step 8 completed\n\n[Step 8 detailed reference]({prefix}STEP_08_README.md). Ten interactive student-test Folium maps cover 19,160 observations and 277 separate saved route segments. Layers show GPS/candidates, frozen RF selections, Viterbi-selected arcs, partial-arc reconstructed routes/intermediates, optional evaluation-only references, gaps/unreachable markers, direction and bounded context. Before/After/Compare controls and the relative trip index work without a Python server; local libraries are bundled and OSM tiles need internet.\n\nLaptop 1 commands (from laptop1_backend):\n\n```powershell\n.\\.venv\\Scripts\\python.exe scripts\\visualize_step8.py\nStart-Process .\\outputs\\step8\\index.html\n```\n\nExamples: 00000009 improvement (+6.667 pp), 00000056 candidate ambiguity, 00000076 gaps and 00000065 decline (−3.306 pp). Metrics are unchanged Step 7 measurements. New map_visualization.py and visualize_step8.py/preview_step8.py/verify_step8.py/document_step8.py expose layer/HTML builders, generation, live browser verification, integrity checks and reporting; contracts and complete commands are in the reference. Outputs/step8 holds maps, local assets, GeoJSON, metadata, relative index/examples, previews, summary and verification. No dependencies added.\n\n17 focused tests; full suite **{tests['tests']} passed**, zero failures/errors/skips. All ten maps and index opened in Chrome; popups/toggles/reference isolation worked. Verification checked 147,396 coordinate pairs and 745 unchanged protected files. A second run reused all ten maps. No production classifiers, optimiser or decoder jobs were rerun; earlier per-step READMEs remain intact.\n\n- [x] Step 8 interactive visualisations, portability, examples, tests, verification and documentation.\n- [ ] Step 9 FastAPI; not started. Streamlit, two-laptop integration and deployment remain pending. Laptop 2 remains a documentation-only placeholder.\n\nChangelog — 2026-11-18: completed Step 8 using saved Step 7 data. Stop here; Step 9 requires explicit authorisation.\n"
        path.write_text(old+marker+addition,encoding='utf-8')
    print('Step 8 detailed reference, summary and all three READMEs updated.')


if __name__=='__main__':
    p=argparse.ArgumentParser(description=__doc__);p.add_argument('--output',type=Path,default=B/'outputs/step8');a=p.parse_args();document(a.output)
